    if (selectedProtocol === undefined) return undefined;

    const protocolIndex = protocols.indexOf(selectedProtocol);
    if (protocolIndex === -1) {
      throw new ERR_TLS_ALPN_CALLBACK_INVALID_RESULT(selectedProtocol, protocols);
    }
